package fixture_test

import (
    "reflect"
    "testing"
    f "fixture"
)

func TestChangingContract(t *testing.T) {
    input := []string{"  alpha "," ","雪","beta ",""}
    original := append([]string(nil), input...)
    records := f.Produce(input)
    expected := []f.Record{{ID:1,Text:"alpha"},{ID:3,Text:"雪"},{ID:4,Text:"beta"}}
    if !reflect.DeepEqual(records,expected) { t.Fatalf("records: %v",records) }
    if !reflect.DeepEqual(f.Consume(records),[]string{"1:alpha","3:雪","4:beta"}) { t.Fatal("consumer") }
    if f.Render(records) != "1:alpha\n3:雪\n4:beta" { t.Fatal("render") }
    if !reflect.DeepEqual(records,expected) || !reflect.DeepEqual(input,original) { t.Fatal("mutation") }
    kept,dropped := f.Stats(input)
    if kept != 3 || dropped != 2 { t.Fatal("stats") }
    if len(f.Produce(nil))!=0 || len(f.Consume(nil))!=0 || f.Render(nil)!="" { t.Fatal("empty") }
    kept,dropped=f.Stats([]string{"", "  "})
    if kept!=0 || dropped!=2 { t.Fatal("blank stats") }
    if !reflect.DeepEqual(f.Consume([]f.Record{{8,"x"},{2,"x"}}),[]string{"8:x","2:x"}) { t.Fatal("order/id preservation") }
}
